                    SnailSpringContext.getContext().publishEvent(new SnailChannelReconnectEvent());
                    channel = connection();
                    GrpcChannel.setChannel(channel);
                } catch (Exception e) {
                    SnailJobLog.LOCAL.error("reconnect error ", e);
                }
            }
        }, 0, 10, TimeUnit.SECONDS);

    }

